var t=[{title:`Tidsskalor`,text:`En mikrocykel är en kort återkommande period, ofta en vecka. En mesocykel är ett block på flera veckor med ett huvudfokus. En makrocykel omfattar en längre säsong eller målperiod. De här namnen hjälper vid planering, och längderna varierar från person till person.`},{title:`Tre angreppssätt`,text:`Linjär progression ändrar variabler långsamt i en allmän riktning, till exempel från fler repetitioner med lättare vikter till färre med tyngre. Vågformad träning ändrar repetitionsmål eller intensitet oftare, till exempel tungt på måndag och måttligt på torsdag. Blockperiodisering kör faser efter varandra, var och en inriktad på en specifik förmåga.`},{title:`Vad forskningen visar`,text:`Studier som jämför upplägg med samma volym hittar möjliga styrkefördelar för periodiserad jämfört med icke-periodiserad träning, och för vågformade upplägg hos tränade personer. Skillnaderna i muskeltillväxt är mindre konsekventa. ACSM:s ställningstagande 2026 fann ingen konsekvent fördel för muskeltillväxt av att enbart lägga till periodisering. Ett mer komplicerat upplägg är inte automatiskt ett bättre.`},{title:`Exempel`,text:`Som nybörjare kan du upprepa en liten uppsättning huvudövningar i sex veckor och sakta öka repetitioner eller vikt. Gör en övning svårare i takt med att tekniken blir bättre. Mer avancerade lyftare kan göra tre veckor med större volym, därefter en tyngre fas och en lättare återhämtningsvecka, beroende på hur de svarar.`},{title:`Så använder du TrainUp`,text:`Ditt program omfattar 4 veckor, och vecka 4 är en lättare avlastningsvecka. Ditt mål, din konditionsnivå och din återkoppling väger tyngre än en avancerad kalender. Ett nytt program kommer bara när du skapar det på nytt, och det ändras ett steg i taget utifrån dina senaste pass.`}];var n=[{label:`Systematisk översikt av periodisering och träningsresultat`,url:`https://pubmed.ncbi.nlm.nih.gov/35044672/`},{label:`ACSM:s ställningstagande 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`},{label:`ACSM:s vägledning om progressionsmodell`,url:`https://pubmed.ncbi.nlm.nih.gov/11828249/`}];var a={sections:t,sources:n};export{a as default,t as sections,n as sources};